// import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { SplitIconButtonProps } from "./split-icon-button.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

import { IconButtonClasses } from "../icon-button";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "SplitIconButton";

// Generate child element class names for the component, should match available style slots
export const SplitIconButtonClasses = {
  root: "exp-textura_split-icon-button",
  leading: "exp-textura_split-icon-button_leading",
  trailing: "exp-textura_split-icon-button_trailing",
  sm: "exp-textura_split-icon-button_sm",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

const generateStyles = (props: SplitIconButtonProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<SplitIconButtonProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    display: "inline-flex",
    position: "relative",
    gap: 0,

    [`.${SplitIconButtonClasses.leading}`]: {
      position: "relative",
      marginInlineEnd: theme.toRem(-1),
      ":dir(ltr)": {
        borderTopRightRadius: 0,
        borderBottomRightRadius: 0,
      },
      ":dir(rtl)": {
        borderTopLeftRadius: 0,
        borderBottomLeftRadius: 0,
      },
      "&:hover": {
        zIndex: 1,
        ...styleSlots?.leadingButtonHover,
      },
      "&:active": {
        ...styleSlots?.leadingButtonPressed,
      },
      "&:disabled, &:disabled:hover": {
        ...styleSlots?.leadingButtonDisabled,
      },
      [`&.${IconButtonClasses.sm}`]: {
        height: "100%",
      },
      ...styleSlots?.leadingButton,
    },

    [`.${SplitIconButtonClasses.trailing}`]: {
      position: "relative",
      width: theme.toRem(16),
      maxWidth: theme.toRem(16),
      ":dir(ltr)": {
        borderTopLeftRadius: 0,
        borderBottomLeftRadius: 0,
      },
      ":dir(rtl)": {
        borderTopRightRadius: 0,
        borderBottomRightRadius: 0,
      },
      [`&.${IconButtonClasses.sm}`]: {
        height: "100%",
      },
      "&:hover": {
        zIndex: 1,
        ...styleSlots?.trailingButtonHover,
      },
      "&:active": {
        ...styleSlots?.trailingButtonPressed,
      },
      "&:disabled, &:disabled:hover": {
        ...styleSlots?.trailingButtonDisabled,
      },
      ...styleSlots?.trailingButton,
    },

    [`&.${SplitIconButtonClasses.sm}`]: {
      [`.${SplitIconButtonClasses.leading}`]: {
        height: theme.toRem(24),
        ...styleSlots?.leadingButtonSm,
      },
      [`.${SplitIconButtonClasses.trailing}`]: {
        height: theme.toRem(24),
        ...styleSlots?.trailingButtonSm,
      },
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledSplitIconButton = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<SplitIconButtonProps>((props) => generateStyles(props));
